import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-revelacion-de-dios', 'B',
 [dict(t=2508, e=2556, titulo='Lo que tú no puedes arreglar', txt='Lo que tú no puedas arreglar, te lo arregla Dios a través de la revelación de lo que tienes que hacer. Si eres gritón, cállate y deja que Dios actúe. Si eres apocado, hoy te desato para que hables en el nombre poderoso de Jesús, y lo que has oído, lo que has vivido, lo puedas transmitir a otros para que sean felices y digas: «No vayas por ahí. Me llevó la tristeza, pero la mano poderosa de Dios me agarró y ahora soy feliz, porque ya entendí que no es por ahí, porque hay caminos que parecen buenos, pero su finalidad es de muerte.»'),
  dict(t=3304, e=3345, titulo='El humilde recibe la revelación', txt='El soberbio, el engreído, no va a aceptar la revelación de Dios. El humilde, el que se postra, el que pasa siete veces por el Jordán. ¿Cuántos saben que el Jordán significa humillación? Nada más pasó siete veces sumergido ahí […] y ya se me reveló que mi verdadero Dios es Jehová.'),
  dict(t=3360, e=3402, titulo='Reconocer al único Dios', txt='Ya no son un montón de dioses con «d» minúscula; ahora son un montón de basura que ya no quiero. Yo reconozco al único Dios, a Jehová de los ejércitos. ¿Cuántos quieren reconocer a Jehová hoy? ¿Cuántos quieren reconocer al Hijo? Porque por el Hijo es que estamos aquí, a través de su sangre. Realmente, si uno tuviera la revelación, cuando solo menciona la sangre de Cristo estaría gritando: «Gracias, Señor.»')],
 [dict(t=538, txt='Cuando uno va avanzando, no se pone el enemigo contento. Usted está avanzando, está contento, y el enemigo viene y quiere ver cómo lo arremete contra usted.'),
  dict(t=1747, txt='Yo tengo que quedar bien con Dios, no con usted.'),
  dict(t=4732, txt='Acuérdese que el cristiano no es feliz de afuera para adentro. El cristiano es feliz de adentro hacia afuera.')],
 ['«El soberbio no va a aceptar la revelación de Dios.» ¿En qué área de tu vida necesitas humillarte hoy para que Dios te muestre qué hacer?',
  'El predicador dice que hay caminos que parecen buenos, pero terminan en muerte. ¿Hay algún camino así en tu vida que Dios te esté pidiendo dejar?',
  '¿Qué cambiaría en tu día si recordaras con revelación lo que hizo la sangre de Cristo por ti?'],
 inicio=539)
